    public static void testNamesAreInternedAndWellKnownIdsResolve() {
        emon.Port.Cells ar = emon.Port.newCells();
        int d = ptParseText(emon.Testport.textBlob("<</Type /Page /Kids [1 0 R] /Type#20X /Type /Media#42ox [0 0 612.5 792]>>"), ar);
        int ty = Pdflex.plDictGet(ar, d, Pdfnames.pnType());
        int kids = Pdflex.plDictGet(ar, d, Pdfnames.pnKids());
        int mb = Pdflex.plDictGet(ar, d, Pdfnames.pnMediaBox());
        int kid0 = Pdflex.plFirst(ar, kids);
        emon.Testport.assertThat(d != 0, "parsed");
        emon.Testport.assertEq(Pdflex.plKindOf(ar, d), Pdflex.plKDict(), "a dictionary");
        emon.Testport.assertEq(Pdflex.plKindOf(ar, ty), Pdflex.plKName(), "/Type is a name");
        emon.Testport.assertThat(Pdflex.plNameIs(ar, ty, Pdfnames.pnType()) == 0, "/Page is not /Type");
        emon.Testport.assertEq(Pdflex.plDictGet(ar, d, Pdfnames.pnLength()), 0, "an absent key answers 0");
        emon.Testport.assertEq(Pdflex.plKindOf(ar, kids), Pdflex.plKArray(), "/Kids is an array");
        emon.Testport.assertEq(Pdflex.plCount(ar, kids), 1, "one kid");
        emon.Testport.assertEq(Pdflex.plKindOf(ar, kid0), Pdflex.plKRef(), "a reference");
        emon.Testport.assertEq(Pdflex.plIntValue(ar, kid0), 1, "to object 1");
        // `/Media#42ox` is `/MediaBox`: the escape is decoded BEFORE interning.
        emon.Testport.assertThat(mb != 0, "/Media#42ox finds /MediaBox");
        emon.Testport.assertEq(Pdflex.plCount(ar, mb), 4, "four numbers");
        // The first /Type is /Page, the key written twice is /Type#20X, and
        // the last /Type wins: its value is the LAST one.
        emon.Testport.assertEq(Pdflex.plKindOf(ar, ty), Pdflex.plKName(), "last /Type");
    }
