    public static void testEveryTruncationOfAFixtureParsesOrNamesAnError() {
        byte[] f = emon.Testport.testFile("pdf/minimal.pdf");
        int n = emon.Port.blobLen(f);
        emon.Port.Cells cut = emon.Port.newCells();
        emon.Port.Cells ar = emon.Port.newCells();
        int cutn = 0;
        int i = 0;
        int guard = 0;
        int at = 0;
        int h = 0;
        int before = 0;
        while (cutn < (n + 1)) {
            emon.Port.cellsDrop(cut, 0);
            i = 0;
            while (i < cutn) {
                emon.Port.cellsPush(cut, emon.Port.blobU8(f, i));
                i += 1;
            }
            // As a token-level object stream from 0.
            Pdflex.plInit(ar);
            Pdflex.plSeek(ar, 0, cutn);
            guard = 0;
            h = 1;
            while ((h != 0) && (guard < 2000)) {
                before = Pdflex.plPos(ar);
                h = Pdflex.plParse(emon.Port.srcOfBlob(emon.Testport.cellsBlob(cut)), ar);
                if ((h != 0) && (Pdflex.plPos(ar) <= before)) {
                    h = 0;
                }
                guard += 1;
            }
            // And as an indirect object at the start of every line.
            at = 0;
            while (at < cutn) {
                Pdflex.plInit(ar);
                Pdflex.plSeek(ar, 0, cutn);
                Pdflex.plParseIndirect(emon.Port.srcOfBlob(emon.Testport.cellsBlob(cut)), ar, at);
                // a stream's data ends inside the blob
                emon.Testport.assertThat(Pdflex.plPos(ar) <= cutn, "the parse never ran past the end");
                at = ptNl(f, at) + 1;
            }
            cutn += 1;
        }
    }
